{"code":"def transform(g):
    # concentric symmetric design: non-background symbols encode successive layers
    h,w=len(g),len(g[0]); bg=max(set(x for r in g for x in r), key=lambda x:sum(v==x for r in g for v in r))
    colors=[]
    for x in sorted(set(x for r in g for x in r), key=lambda x:sum(v==x for r in g for v in r)):
        if x!=bg: colors.append(x)
    # center marker is rarest
    n=2*len(colors)+1
    out=[[bg]*n for _ in range(n)]; c=n//2
    for k,col in enumerate(reversed(colors)):
        d=k+1
        for i in range(n):
            for j in range(n):
                if min(i,j,n-1-i,n-1-j)==d-1: out[i][j]=col
    # center rarest
    out[c][c]=colors[0] if colors else bg
    return out"}

